import { useState, useRef, useEffect } from 'react';
import { servicioPerfil } from '../../services/profileService';

const EditProfileModal = ({
    usuario,
    perfil,
    setPerfil,
    onClose,
    avatarUrl,
    avatarFallback
}) => {
    // 1. Estados locales exclusivos del Modal
    const [formData, setFormData] = useState({
        username: perfil?.username || '',
        biografia: perfil?.biografia || '',
        peso: perfil?.peso || '',
        altura: perfil?.altura || ''
    });
    const [guardando, setGuardando] = useState(false);
    const [errorModal, setErrorModal] = useState('');
    const [exitoModal, setExitoModal] = useState('');

    const fileInputRef = useRef(null);

    // Sincronizar el form si el perfil cambia o se carga tarde
    useEffect(() => {
        if (perfil) {
            setFormData({
                username: perfil.username || '',
                biografia: perfil.biografia || '',
                peso: perfil.peso || '',
                altura: perfil.altura || ''
            });
        }
    }, [perfil]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // 2. Lógica para guardar la información de texto
    const manejarGuardar = async () => {
        setErrorModal('');
        setExitoModal('');
        setGuardando(true);

        const payload = {
            username: formData.username,
            biografia: formData.biografia,
            peso: formData.peso === '' ? null : Number(formData.peso),
            altura: formData.altura === '' ? null : Number(formData.altura)
        };

        const { data, error } = await servicioPerfil.actualizarPerfil(usuario.id, payload);

        if (!error && data) {
            setPerfil(data); // Actualizamos el estado global en Profile.jsx
            setExitoModal('¡Perfil actualizado correctamente!');
            setTimeout(() => {
                onClose();
            }, 1500);
        } else {
            console.error(error);
            setErrorModal('Error al actualizar el perfil. Comprueba tu conexión o que tu nombre de usuario no esté ocupado.');
        }
        setGuardando(false);
    };

    const manejarClickAvatar = () => {
        fileInputRef.current.click();
    };

    // 3. Lógica para manejar el Avatar (Compresión y control de subida intactos)
    const manejarSeleccionArchivo = async (e) => {
        setErrorModal('');
        setExitoModal('');
        const archivo = e.target.files[0];
        if (!archivo) return;

        // Validar tamaño máximo (5MB)
        const sizeLimit = 5 * 1024 * 1024;
        if (archivo.size > sizeLimit) {
            setErrorModal('El archivo es demasiado grande. Por favor, selecciona una imagen de menos de 5MB.');
            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        // Validar que sea un formato de imagen permitido
        const validExtensions = ['.jpg', '.jpeg', '.png', '.webp'];
        const fileName = archivo.name.toLowerCase();
        const hasValidExtension = validExtensions.some(ext => fileName.endsWith(ext));

        const validMsTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
        const hasValidType = !archivo.type || validMsTypes.includes(archivo.type.toLowerCase());

        if (!hasValidExtension || !hasValidType) {
            setErrorModal('Por favor, selecciona un archivo de imagen válido (JPG, PNG o WebP).');
            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        setGuardando(true);
        const resultadoSubida = await servicioPerfil.subirAvatar(archivo, usuario.id);

        if (resultadoSubida) {
            const { publicUrl, filePath } = resultadoSubida;

            const { data, error } = await servicioPerfil.actualizarPerfil(usuario.id, { avatar_url: publicUrl });
            if (!error && data) {
                setPerfil(data);
                setExitoModal('¡Foto de perfil actualizada!');
                setTimeout(() => setExitoModal(''), 2000);
            } else {
                await servicioPerfil.eliminarAvatar(filePath);
                setErrorModal('Oops, la foto se subió pero hubo un problema guardándola en tu perfil. Inténtalo de nuevo.');
            }
        } else {
            setErrorModal('Error de red. Asegúrate de tener conexión a internet o de que la imagen no esté corrupta.');
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
        setGuardando(false);
    };

    const handleCloseModal = () => {
        onClose();
        setErrorModal('');
        setExitoModal('');
    };

    return (
        <div className="modal-overlay" onClick={handleCloseModal}>
            <div className="modal-custom" onClick={(e) => e.stopPropagation()}>
                <div className="modal-header-custom">
                    <h5 className="modal-title">Editar Perfil</h5>
                    <button className="btn-close-custom" onClick={handleCloseModal}>
                        <i className="bi bi-x-lg"></i>
                    </button>
                </div>

                <div className="modal-body-custom">
                    {errorModal && (
                        <div className="alert alert-danger d-flex align-items-center py-2 px-3 small rounded" role="alert">
                            <i className="bi bi-exclamation-triangle-fill me-2 fs-5"></i>
                            <div>{errorModal}</div>
                        </div>
                    )}
                    {exitoModal && (
                        <div className="alert alert-success d-flex align-items-center py-2 px-3 small rounded" role="alert">
                            <i className="bi bi-check-circle-fill me-2 fs-5"></i>
                            <div>{exitoModal}</div>
                        </div>
                    )}

                    {/* Avatar Edit */}
                    <div className="text-center">
                        <div
                            className="edit-avatar-container"
                            onClick={manejarClickAvatar}
                        >
                            <div className="edit-avatar overflow-hidden bg-white d-flex align-items-center justify-content-center">
                                {avatarUrl ? (
                                    <img src={avatarUrl} alt="Avatar" loading="lazy" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                ) : (
                                    avatarFallback
                                )}
                            </div>
                            <div className="edit-icon-overlay">
                                <i className="bi bi-camera-fill"></i>
                            </div>
                        </div>
                        <input
                            type="file"
                            ref={fileInputRef}
                            style={{ display: 'none' }}
                            accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                            onChange={manejarSeleccionArchivo}
                        />
                    </div>

                    {/* Inputs */}
                    <div className="form-floating-custom">
                        <label className="input-label">Nombre de Usuario</label>
                        <input
                            type="text"
                            className="form-control-custom"
                            name="username"
                            placeholder="Tu nombre de usuario"
                            value={formData.username}
                            onChange={handleChange}
                        />
                    </div>

                    <div className="row">
                        <div className="col-6">
                            <div className="form-floating-custom">
                                <label className="input-label">Peso (kg)</label>
                                <input
                                    type="number"
                                    className="form-control-custom text-center"
                                    name="peso"
                                    placeholder="00"
                                    value={formData.peso}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>
                        <div className="col-6">
                            <div className="form-floating-custom">
                                <label className="input-label">Altura (cm)</label>
                                <input
                                    type="number"
                                    className="form-control-custom text-center"
                                    name="altura"
                                    placeholder="000"
                                    value={formData.altura}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>
                    </div>

                    <div className="form-floating-custom">
                        <label className="input-label">Biografía</label>
                        <textarea
                            className="form-control-custom"
                            rows="3"
                            name="biografia"
                            placeholder="Escribe algo inspirador..."
                            value={formData.biografia}
                            onChange={handleChange}
                            style={{ resize: 'none' }}
                        ></textarea>
                    </div>

                    <div className="modal-footer-custom">
                        <button className="btn-cancel" onClick={handleCloseModal} disabled={guardando}>
                            Cancelar
                        </button>
                        <button className="btn-save" onClick={manejarGuardar} disabled={guardando}>
                            {guardando ? 'Guardando...' : 'Guardar Cambios'}
                        </button>
                    </div>

                </div>
            </div>
        </div>
    );
};

export default EditProfileModal;

import React from 'react';

const TextFeed = ({
    publicaciones,
    usuario,
    nombreMostrar,
    avatarUrl,
    avatarFallback,
    esMiPerfil,
    setModalPublicacion,
    manejarLike,
    toggleComentariosTexto,
    comentariosTextosAbiertos,
    comentariosTextos,
    nuevosComentariosTextos,
    setNuevosComentariosTextos,
    manejarEnviarComentarioTexto,
    enviandoComentarioTexto
}) => {
    const textos = publicaciones.filter(p => !p.image_url);

    return (
        <div className="text-posts-feed mt-4" style={{ maxWidth: '600px', margin: '0 auto' }}>
            {textos.length > 0 ? (
                textos.map(post => (
                    <div key={post.id} className="card shadow-sm mb-3 border-0 rounded-4">
                        <div className="card-body">
                            <div className="d-flex align-items-center mb-3">
                                <div className="bg-primary text-white rounded-circle d-flex align-items-center justify-content-center me-3" style={{ width: '40px', height: '40px' }}>
                                    {avatarUrl ? (
                                        <img src={avatarUrl} alt="Avatar" loading="lazy" style={{ width: '100%', height: '100%', objectFit: 'cover' }} className="rounded-circle" />
                                    ) : (
                                        avatarFallback
                                    )}
                                </div>
                                <div>
                                    <h6 className="mb-0 fw-bold">{nombreMostrar}</h6>
                                    <small className="text-muted">{new Date(post.created_at || post.fechaCreacion || Date.now()).toLocaleDateString()}</small>
                                </div>
                            </div>
                            <p className="card-text">{post.texto}</p>

                            {/* Footer para posts de texto en el perfil */}
                            <div className="d-flex align-items-center mt-3 pt-3 border-top">
                                <button
                                    className={`btn btn-sm ${post.likedByMe ? 'text-primary' : 'text-muted'} me-3 p-0 border-0 bg-transparent`}
                                    onClick={() => manejarLike(post.id)}
                                >
                                    <i className={post.likedByMe ? "bi bi-heart-fill me-1" : "bi bi-heart me-1"}></i>
                                    {post.likesCount > 0 && post.likesCount} {post.likesCount === 1 ? 'Me gusta' : (post.likesCount === 0 ? 'Me gusta' : 'Me gustas')}
                                </button>
                                <div className="d-flex align-items-center">
                                    <button
                                        className="btn btn-sm text-muted p-0 border-0 bg-transparent"
                                        onClick={() => toggleComentariosTexto(post.id)}
                                    >
                                        <i className="bi bi-chat me-1"></i> Comentar
                                    </button>
                                    {post.commentsCount > 0 && (
                                        <span
                                            className="text-muted ms-2 px-2 text-decoration-underline-hover"
                                            style={{ fontSize: '0.875rem', cursor: 'pointer' }}
                                            onClick={() => toggleComentariosTexto(post.id)}
                                        >
                                            {post.commentsCount} {post.commentsCount === 1 ? 'comentario' : 'comentarios'}
                                        </span>
                                    )}
                                </div>
                            </div>

                            {/* Sección Expandible de Comentarios en Textos */}
                            {comentariosTextosAbiertos[post.id] && (
                                <div className="mt-3 pt-3 border-top pb-3">
                                    {/* Lista de comentarios */}
                                    <div className="comments-list mb-3" style={{ maxHeight: '200px', overflowY: 'auto' }}>
                                        {!comentariosTextos[post.id] ? (
                                            <div className="text-center py-2"><span className="spinner-border spinner-border-sm text-primary"></span></div>
                                        ) : comentariosTextos[post.id].length === 0 ? (
                                            <p className="text-muted small text-center my-2">¡Sé el primero en comentar!</p>
                                        ) : (
                                            comentariosTextos[post.id].map(comentario => (
                                                <div key={comentario.id} className="d-flex mb-2 align-items-start gap-2">
                                                    <div className="bg-secondary text-white rounded-circle d-flex align-items-center justify-content-center flex-shrink-0" style={{ width: '28px', height: '28px', fontSize: '12px' }}>
                                                        {comentario.profiles?.avatar_url ? (
                                                            <img src={comentario.profiles.avatar_url} alt="Avatar" className="w-100 h-100 rounded-circle object-fit-cover" />
                                                        ) : (
                                                            (comentario.profiles?.username || 'U').charAt(0).toUpperCase()
                                                        )}
                                                    </div>
                                                    <div className="bg-light rounded p-2 px-3 fw-normal" style={{ fontSize: '13px', maxWidth: '85%' }}>
                                                        <span className="fw-bold me-2">{comentario.profiles?.username || 'Usuario'}</span>
                                                        <span>{comentario.text}</span>
                                                    </div>
                                                </div>
                                            ))
                                        )}
                                    </div>

                                    {/* Input para nuevo comentario */}
                                    <div className="d-flex align-items-center gap-2">
                                        <div className="bg-primary text-white rounded-circle d-flex align-items-center justify-content-center flex-shrink-0 shadow-sm" style={{ width: '36px', height: '36px', fontSize: '14px' }}>
                                            {(usuario?.user_metadata?.nombre_usuario || usuario?.email || '?').charAt(0).toUpperCase()}
                                        </div>
                                        <div className="input-group">
                                            <input
                                                type="text"
                                                className="form-control rounded-pill bg-light border-0 px-4 py-2"
                                                style={{ fontSize: '13px', boxShadow: 'inset 0 1px 2px rgba(0,0,0,0.05)' }}
                                                placeholder="Escribe un comentario..."
                                                value={nuevosComentariosTextos[post.id] || ''}
                                                onChange={(e) => setNuevosComentariosTextos(prev => ({ ...prev, [post.id]: e.target.value }))}
                                                onKeyDown={(e) => e.key === 'Enter' && manejarEnviarComentarioTexto(post.id)}
                                                disabled={enviandoComentarioTexto[post.id]}
                                            />
                                            <button
                                                className="btn text-primary border-0 position-absolute end-0 top-50 translate-middle-y z-1 me-1 p-1 px-2 pb-0"
                                                onClick={() => manejarEnviarComentarioTexto(post.id)}
                                                disabled={!nuevosComentariosTextos[post.id]?.trim() || enviandoComentarioTexto[post.id]}
                                            >
                                                {enviandoComentarioTexto[post.id] ? (
                                                    <span className="spinner-border spinner-border-sm"></span>
                                                ) : (
                                                    <i className="bi bi-send-fill fs-6"></i>
                                                )}
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            )}

                        </div>
                    </div>
                ))
            ) : (
                <div className="text-center p-5 text-muted">
                    <i className="bi bi-chat-square-text fs-1"></i>
                    <p className="mt-2 text-muted">Aún no hay publicaciones de texto.</p>
                    {esMiPerfil && <button className="btn btn-outline-primary mt-2" onClick={() => setModalPublicacion(true)}>Crear publicación</button>}
                </div>
            )}
        </div>
    );
};

export default TextFeed;

import { createContext, useState, useEffect, useContext } from 'react';
import { servicioAutenticacion } from '../services/authService';
import { supabase } from '../supabaseClient';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
    const [usuario, setUsuario] = useState(null);
    const [cargando, setCargando] = useState(true);

    useEffect(() => {
        servicioAutenticacion.obtenerSesionActual().then(user => {
            setUsuario(user);
            setCargando(false);
        });

        const { data: authListener } = supabase.auth.onAuthStateChange((event, session) => {
            /*
             * Monitor de estado de autenticación de Supabase.
             * Actualiza el usuario y el estado de carga automáticamente.
             */
            setUsuario(session?.user || null);
            setCargando(false);
        });

        return () => {
            authListener.subscription.unsubscribe();
        };
    }, []);

    const iniciarSesion = async (email, contrasena) => {
        const { user, error } = await servicioAutenticacion.iniciarSesion(email, contrasena);
        if (error) {
            throw error;
        }
        return user;
    };

    const cerrarSesion = async () => {
        await servicioAutenticacion.cerrarSesion();
    };

    const valorCompartido = {
        usuario,
        iniciarSesion,
        iniciarSesionGoogle: servicioAutenticacion.iniciarSesionGoogle,
        cerrarSesion,
        cargando
    };

    return (
        <AuthContext.Provider value={valorCompartido}>
            {!cargando && children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => useContext(AuthContext);

import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { useAuth } from '../context/AuthContext';
import { servicioPerfil } from '../services/profileService';
import { servicioPublicaciones } from '../services/postService';
import TextFeed from '../components/profile/TextFeed';
import PhotoGrid from '../components/profile/PhotoGrid';
import EditProfileModal from '../components/profile/EditProfileModal';
import CreatePostModal from '../components/profile/CreatePostModal';
import PhotoViewerModal from '../components/profile/PhotoViewerModal';
import './Profile.css';

const Profile = () => {
    const { usuario } = useAuth();
    const { id: paramId } = useParams();
    const profileId = paramId || usuario?.id;
    const esMiPerfil = !paramId || paramId === usuario?.id;

    const [perfil, setPerfil] = useState(null);
    const [cargando, setCargando] = useState(true);
    const [editando, setEditando] = useState(false);
    const [activeTab, setActiveTab] = useState('fotos'); // 'fotos' o 'textos'



    // Estado para publicaciones
    const [publicaciones, setPublicaciones] = useState([]);

    // Estado para nueva publicación (para el modal)
    const [modalPublicacion, setModalPublicacion] = useState(false);

    // Estado para ver fotos en grande
    const [fotoAmpliada, setFotoAmpliada] = useState(null);

    // Estados para comentarios en el visor de fotos
    const [comentariosVisor, setComentariosVisor] = useState([]);
    const [cargandoComentarios, setCargandoComentarios] = useState(false);
    // Estados para comentarios en posts de texto del perfil
    const [comentariosTextos, setComentariosTextos] = useState({});
    const [comentariosTextosAbiertos, setComentariosTextosAbiertos] = useState({});
    const [nuevosComentariosTextos, setNuevosComentariosTextos] = useState({});
    const [enviandoComentarioTexto, setEnviandoComentarioTexto] = useState({});

    // Estados para seguidores
    const [seguidoresStats, setSeguidoresStats] = useState({ followers: 0, following: 0 });
    const [loSigo, setLoSigo] = useState(false);
    const [cargandoFollow, setCargandoFollow] = useState(false);
    const [mostrarModalUnfollow, setMostrarModalUnfollow] = useState(false);

    // Cargar perfil al montar o cambiar de usuario
    useEffect(() => {
        if (profileId) {
            cargarPerfil();
            cargarPublicaciones();
            cargarFollows();
        }
    }, [profileId, usuario.id]);

    const cargarFollows = async () => {
        const stats = await servicioPerfil.obtenerContadoresSeguidores(profileId);
        setSeguidoresStats(stats);

        if (!esMiPerfil) {
            const meSigue = await servicioPerfil.verificarSiSigue(usuario.id, profileId);
            setLoSigo(meSigue);
        }
    };

    const cargarPublicaciones = async () => {
        const posts = await servicioPublicaciones.obtenerPublicacionesUsuario(profileId);
        if (posts) {
            // Cargar likes y conteo de comentarios iniciales para cada publicación
            const postsConMetadatos = await Promise.all(posts.map(async (post) => {
                const { count: likesCount } = await servicioPublicaciones.obtenerLikesDePublicacion(post.id);
                const diLike = await servicioPublicaciones.verificarSiDiLike(post.id, usuario.id);
                const commentsCount = await servicioPublicaciones.obtenerCantidadComentariosDePublicacion(post.id);
                return { ...post, likesCount: likesCount || 0, likedByMe: diLike, commentsCount: commentsCount || 0 };
            }));

            setPublicaciones(postsConMetadatos);
        }
    }

    const cargarPerfil = async () => {
        setCargando(true);
        const datos = await servicioPerfil.obtenerPerfil(profileId);

        if (datos) {
            setPerfil(datos);
        }
        setCargando(false);
    };

    const manejarFollowToggle = async () => {
        if (cargandoFollow) return;

        if (loSigo) {
            setMostrarModalUnfollow(true);
        } else {
            setCargandoFollow(true);
            const exito = await servicioPerfil.seguirUsuario(usuario.id, profileId);
            if (exito) {
                setLoSigo(true);
                setSeguidoresStats(prev => ({ ...prev, followers: prev.followers + 1 }));
            }
            setCargandoFollow(false);
        }
    };

    const confirmarUnfollow = async () => {
        setCargandoFollow(true);
        const exito = await servicioPerfil.dejarDeSeguirUsuario(usuario.id, profileId);
        if (exito) {
            setLoSigo(false);
            setSeguidoresStats(prev => ({ ...prev, followers: prev.followers - 1 }));
        }
        setCargandoFollow(false);
        setMostrarModalUnfollow(false);
    };



    const manejarLike = async (postId) => {
        // Encontrar el post actual
        const postIndex = publicaciones.findIndex(p => p.id === postId);
        if (postIndex === -1) return;

        const post = publicaciones[postIndex];
        const nuevoEstadoLike = !post.likedByMe;

        // Actualización optimista de la UI
        const nuevasPublicaciones = [...publicaciones];
        nuevasPublicaciones[postIndex] = {
            ...post,
            likedByMe: nuevoEstadoLike,
            likesCount: nuevoEstadoLike ? post.likesCount + 1 : Math.max(0, post.likesCount - 1)
        };
        setPublicaciones(nuevasPublicaciones);

        // Si la foto ampliada es esta misma, actualizarla también
        if (fotoAmpliada && fotoAmpliada.id === postId) {
            setFotoAmpliada({
                ...fotoAmpliada,
                likedByMe: nuevoEstadoLike,
                likesCount: nuevoEstadoLike ? fotoAmpliada.likesCount + 1 : Math.max(0, fotoAmpliada.likesCount - 1)
            });
        }

        try {
            if (nuevoEstadoLike) {
                await servicioPublicaciones.darLike(postId, usuario.id);
            } else {
                await servicioPublicaciones.quitarLike(postId, usuario.id);
            }
        } catch (error) {
            console.error("Error al cambiar like:", error);
            // Revertir en caso de error
            setPublicaciones(publicaciones);
            if (fotoAmpliada && fotoAmpliada.id === postId) {
                setFotoAmpliada(post);
            }
        }
    };

    const abrirVisor = async (post) => {
        setFotoAmpliada(post);
        setCargandoComentarios(true);
        setComentariosVisor([]);

        try {
            const comments = await servicioPublicaciones.obtenerComentariosDePublicacion(post.id);
            setComentariosVisor(comments);
        } catch (error) {
            console.error("Error cargando comentarios del visor:", error);
        } finally {
            setCargandoComentarios(false);
        }
    };

    const toggleComentariosTexto = async (postId) => {
        if (comentariosTextosAbiertos[postId]) {
            setComentariosTextosAbiertos(prev => ({ ...prev, [postId]: false }));
            return;
        }

        setComentariosTextosAbiertos(prev => ({ ...prev, [postId]: true }));

        if (!comentariosTextos[postId]) {
            const commentsData = await servicioPublicaciones.obtenerComentariosDePublicacion(postId);
            setComentariosTextos(prev => ({ ...prev, [postId]: commentsData }));
        }
    };

    const manejarEnviarComentarioTexto = async (postId) => {
        const texto = nuevosComentariosTextos[postId];
        if (!texto || !texto.trim() || enviandoComentarioTexto[postId]) return;

        setEnviandoComentarioTexto(prev => ({ ...prev, [postId]: true }));

        try {
            const nuevoComentario = await servicioPublicaciones.agregarComentario(postId, usuario.id, texto);
            if (nuevoComentario) {
                setComentariosTextos(prev => ({
                    ...prev,
                    [postId]: [...(prev[postId] || []), nuevoComentario]
                }));
                setNuevosComentariosTextos(prev => ({ ...prev, [postId]: '' }));

                // Actualizar optimísticamente la cuenta de comentarios en el post
                const postIndex = publicaciones.findIndex(p => p.id === postId);
                if (postIndex !== -1) {
                    const nuevasPublicaciones = [...publicaciones];
                    nuevasPublicaciones[postIndex] = {
                        ...nuevasPublicaciones[postIndex],
                        commentsCount: (nuevasPublicaciones[postIndex].commentsCount || 0) + 1
                    };
                    setPublicaciones(nuevasPublicaciones);
                }
            }
        } catch (err) {
            console.error("Error al enviar comentario de texto", err);
        } finally {
            setEnviandoComentarioTexto(prev => ({ ...prev, [postId]: false }));
        }
    };

    const nombreMostrar = perfil?.username || perfil?.raw_user_meta_data?.nombre_usuario || 'Usuario';
    const rol = perfil?.rol || 'cliente';
    const avatarUrl = perfil?.avatar_url;
    const avatarFallback = !avatarUrl ? nombreMostrar.charAt(0).toUpperCase() : null;

    if (cargando) return (
        <div className="d-flex justify-content-center align-items-center vh-100 bg-light">
            <div className="spinner-grow text-primary" role="status">
                <span className="visually-hidden">Cargando...</span>
            </div>
        </div>
    );

    return (
        <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh' }}>
            <Navbar />

            <div className="profile-container">

                {/* Tarjeta de información del perfil */}
                <div className="profile-card">
                    <div className="profile-header">
                        <div className="cover-photo"></div>
                        <div className="profile-avatar-container">
                            <div className="profile-avatar overflow-hidden bg-white d-flex align-items-center justify-content-center">
                                {avatarUrl ? (
                                    <img src={avatarUrl} alt="Avatar" loading="lazy" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                ) : (
                                    avatarFallback
                                )}
                            </div>
                        </div>
                    </div>

                    <div className="profile-info">
                        <h2 className="profile-name">{nombreMostrar}</h2>
                        <p className="text-secondary mb-3">@{perfil?.username || 'usuario'}</p>

                        <div className="mb-4">
                            <span className="profile-role-badge">
                                {rol === 'admin_gym' ? 'Administrador' : 'Atleta FitNation'}
                            </span>
                        </div>

                        {/* Biografía */}
                        <div className="profile-bio-section">
                            <p className="profile-bio-text">
                                {perfil?.biografia || "¡Hola! Soy nuevo en FitNation."}
                            </p>
                        </div>

                        {/* Estadísticas físicas */}
                        <div className="physical-stats-row">
                            <div className="physical-stat-item">
                                <span className="stat-value-big">
                                    {perfil?.peso || '--'} <span className="stat-unit">kg</span>
                                </span>
                                <span className="stat-label-small">Peso</span>
                            </div>
                            <div className="vertical-divider"></div>
                            <div className="physical-stat-item">
                                <span className="stat-value-big">
                                    {perfil?.altura || '--'} <span className="stat-unit">cm</span>
                                </span>
                                <span className="stat-label-small">Altura</span>
                            </div>
                        </div>

                        <div className="mt-4">
                            {esMiPerfil ? (
                                <button className="btn btn-dark rounded-pill px-5 py-2 fw-bold shadow-sm" onClick={() => setEditando(true)}>
                                    Editar Perfil
                                </button>
                            ) : (
                                <button
                                    className={`btn rounded-pill px-5 py-2 fw-bold shadow-sm ${loSigo ? 'btn-outline-dark' : 'btn-primary text-white'}`}
                                    onClick={manejarFollowToggle}
                                    disabled={cargandoFollow}
                                >
                                    {cargandoFollow ? (
                                        <span className="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
                                    ) : loSigo ? 'Siguiendo' : 'Seguir'}
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Estadísticas */}
                    <div className="profile-stats">
                        <div className="stat-item">
                            <span className="stat-value">{publicaciones.length}</span>
                            <span className="stat-label">Posts</span>
                        </div>
                        <div className="stat-item">
                            <span className="stat-value">{seguidoresStats.followers}</span>
                            <span className="stat-label">Seguidores</span>
                        </div>
                        <div className="stat-item">
                            <span className="stat-value">{seguidoresStats.following}</span>
                            <span className="stat-label">Seguidos</span>
                        </div>
                    </div>
                </div>

                {/* Contenido principal */}
                <div className="profile-content-section mt-5">
                    <div className="d-flex justify-content-between align-items-center mb-4">
                        <h5 className="section-title mb-0">Publicaciones</h5>
                        {esMiPerfil && (
                            <button className="btn btn-outline-primary rounded-pill fw-bold btn-sm shadow-sm px-3" onClick={() => setModalPublicacion(true)}>
                                <i className="bi bi-plus-lg me-1"></i> Nuevo Post
                            </button>
                        )}
                    </div>
                    <div className="d-flex justify-content-center border-top pt-3 pb-3 mb-2 gap-4">
                        <button
                            className={`btn ${activeTab === 'fotos' ? 'text-primary fw-bold' : 'text-muted'}`}
                            style={{ border: 'none', background: 'transparent', borderBottom: activeTab === 'fotos' ? '2px solid #0d6efd' : '2px solid transparent', borderRadius: '0' }}
                            onClick={() => setActiveTab('fotos')}
                        >
                            <i className="bi bi-grid-3x3 me-2"></i> Fotos
                        </button>
                        <button
                            className={`btn ${activeTab === 'textos' ? 'text-primary fw-bold' : 'text-muted'}`}
                            style={{ border: 'none', background: 'transparent', borderBottom: activeTab === 'textos' ? '2px solid #0d6efd' : '2px solid transparent', borderRadius: '0' }}
                            onClick={() => setActiveTab('textos')}
                        >
                            <i className="bi bi-justify-left me-2"></i> Publicaciones
                        </button>
                    </div>

                    {activeTab === 'fotos' ? (
                        <PhotoGrid
                            publicaciones={publicaciones}
                            abrirVisor={abrirVisor}
                            nombreMostrar={nombreMostrar}
                            esMiPerfil={esMiPerfil}
                            setModalPublicacion={setModalPublicacion}
                        />
                    ) : (
                        <TextFeed
                            publicaciones={publicaciones}
                            usuario={usuario}
                            nombreMostrar={nombreMostrar}
                            avatarUrl={avatarUrl}
                            avatarFallback={avatarFallback}
                            esMiPerfil={esMiPerfil}
                            setModalPublicacion={setModalPublicacion}
                            manejarLike={manejarLike}
                            toggleComentariosTexto={toggleComentariosTexto}
                            comentariosTextosAbiertos={comentariosTextosAbiertos}
                            comentariosTextos={comentariosTextos}
                            nuevosComentariosTextos={nuevosComentariosTextos}
                            setNuevosComentariosTextos={setNuevosComentariosTextos}
                            manejarEnviarComentarioTexto={manejarEnviarComentarioTexto}
                            enviandoComentarioTexto={enviandoComentarioTexto}
                        />
                    )}
                </div>

            </div>

            {/* Modal de edición de perfil */}
            {editando && (
                <EditProfileModal
                    usuario={usuario}
                    perfil={perfil}
                    setPerfil={setPerfil}
                    onClose={() => setEditando(false)}
                />
            )}

            {/* Modal de CREAR PUBLICACIÓN */}
            {modalPublicacion && (
                <CreatePostModal
                    usuario={usuario}
                    perfil={perfil}
                    onClose={() => setModalPublicacion(false)}
                    avatarUrl={avatarUrl}
                    avatarFallback={avatarFallback}
                    onPostCreated={(nueva) => setPublicaciones([nueva, ...publicaciones])}
                />
            )}

            {/* PREMIUM IMAGE VIEWER MODAL */}
            {fotoAmpliada && (
                <PhotoViewerModal
                    fotoAmpliada={fotoAmpliada}
                    setFotoAmpliada={setFotoAmpliada}
                    usuario={usuario}
                    nombreMostrar={nombreMostrar}
                    avatarUrl={avatarUrl}
                    avatarFallback={avatarFallback}
                    manejarLike={manejarLike}
                    comentariosVisor={comentariosVisor}
                    setComentariosVisor={setComentariosVisor}
                    cargandoComentarios={cargandoComentarios}
                    publicaciones={publicaciones}
                    setPublicaciones={setPublicaciones}
                />
            )}

            {/* Modal de Confirmación de Unfollow */}
            {mostrarModalUnfollow && (
                <div className="modal fade show" style={{ display: 'block', backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1055 }} tabIndex="-1">
                    <div className="modal-dialog modal-dialog-centered" style={{ maxWidth: '350px' }}>
                        <div className="modal-content rounded-4 border-0 shadow-lg">
                            <div className="modal-body text-center p-4">
                                <div className="mb-3 mt-2">
                                    {avatarUrl ? (
                                        <img src={avatarUrl} alt="Avatar" className="rounded-circle" style={{ width: '80px', height: '80px', objectFit: 'cover' }} />
                                    ) : (
                                        <div className="bg-secondary text-white rounded-circle d-inline-flex align-items-center justify-content-center" style={{ width: '80px', height: '80px', fontSize: '32px' }}>
                                            {avatarFallback}
                                        </div>
                                    )}
                                </div>
                                <h5 className="mb-2 fw-bold" style={{ fontSize: '1.1rem' }}>¿Dejar de seguir a @{perfil?.username || 'usuario'}?</h5>
                                <p className="text-muted mb-4 small" style={{ fontSize: '0.9rem' }}>Sus publicaciones ya no aparecerán en tu feed "Siguiendo".</p>

                                <button
                                    className="btn btn-danger w-100 rounded-pill fw-bold mb-2 py-2"
                                    onClick={confirmarUnfollow}
                                    disabled={cargandoFollow}
                                >
                                    {cargandoFollow ? <span className="spinner-border spinner-border-sm"></span> : 'Dejar de seguir'}
                                </button>
                                <button
                                    className="btn btn-light w-100 rounded-pill fw-bold py-2 border"
                                    onClick={() => setMostrarModalUnfollow(false)}
                                    disabled={cargandoFollow}
                                >
                                    Cancelar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

export default Profile;

import { supabase } from '../supabaseClient';
import imageCompression from 'browser-image-compression';

export const servicioPerfil = {
    /**
     * Obtiene el perfil completo de un usuario por su ID.
     * @param {string} userId
     * @returns {object|null} Datos del perfil o null si falla.
     */
    obtenerPerfil: async (userId) => {
        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', userId)
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error("Error obteniendo perfil:", error);
            return null;
        }
    },

    /**
     * Actualiza los datos del perfil.
     * @param {string} userId
     * @param {object} actualizaciones - Objeto con los campos a actualizar (peso, altura, biografia, etc.)
     */
    actualizarPerfil: async (userId, actualizaciones) => {
        try {
            const { data, error } = await supabase
                .from('profiles')
                .update(actualizaciones)
                .eq('id', userId)
                .select(); // <= QUITAR .single() temporalmente aquí

            if (error) throw error;

            // Revisa si trajo al menos 1 fila actualizada
            if (!data || data.length === 0) {
                return { data: null, error: { message: "No se actualizó ninguna fila. ¿Falta la fila de perfil para este usuario o tu política RLS no permite el UPDATE?" } };
            }

            // Retorna la primera de la lista manualmente simulando .single()
            return { data: data[0], error: null };
        } catch (error) {
            console.error("Error actualizando perfil:", error);
            return { data: null, error };
        }
    },

    /**
     * Sube un avatar al bucket 'avatars' y retorna la URL pública.
     * @param {File} archivo - Archivo de imagen seleccionado por el usuario.
     * @param {string} userId - ID del usuario (usado para el nombre del archivo).
     * @returns {string|null} URL pública de la imagen o null si falla.
     */
    subirAvatar: async (archivo, userId) => {
        try {
            const fileExt = archivo.name.split('.').pop();
            const fileName = `${userId}-${Date.now()}.${fileExt}`;
            const filePath = `${fileName}`;

            // Opciones de compresión para el avatar
            const opcionesCompresion = {
                maxSizeMB: 0.5, // Avatares muy ligeros (max 500kb)
                maxWidthOrHeight: 800, // No necesitamos avatares 4K
                useWebWorker: true
            };

            // Comprimir la imagen antes de subirla
            const archivoComprimido = await imageCompression(archivo, opcionesCompresion);

            // 1. Subir a Supabase Storage
            const { error: uploadError } = await supabase.storage
                .from('avatars')
                .upload(filePath, archivoComprimido);

            if (uploadError) throw uploadError;

            // 2. Obtener URL pública
            const { data } = supabase.storage
                .from('avatars')
                .getPublicUrl(filePath);

            return { publicUrl: data.publicUrl, filePath: filePath };
        } catch (error) {
            console.error("Error subiendo avatar:", error);
            return null;
        }
    },

    /**
     * Elimina un archivo del bucket 'avatars'. Útil para revertir subidas si falla la BD.
     * @param {string} filePath - La ruta del archivo a eliminar.
     */
    eliminarAvatar: async (filePath) => {
        try {
            const { error } = await supabase.storage
                .from('avatars')
                .remove([filePath]);

            if (error) throw error;
            return true;
        } catch (error) {
            console.error("Error eliminando avatar huérfano:", error);
            return false;
        }
    },

    // === SISTEMA DE SEGUIDORES ===

    seguirUsuario: async (followerId, followingId) => {
        try {
            const { error } = await supabase
                .from('follows')
                .insert([{ follower_id: followerId, following_id: followingId }]);

            if (error) throw error;
            return true;
        } catch (error) {
            console.error("Error al seguir usuario:", error);
            return false;
        }
    },

    dejarDeSeguirUsuario: async (followerId, followingId) => {
        try {
            const { error } = await supabase
                .from('follows')
                .delete()
                .eq('follower_id', followerId)
                .eq('following_id', followingId);

            if (error) throw error;
            return true;
        } catch (error) {
            console.error("Error al dejar de seguir usuario:", error);
            return false;
        }
    },

    verificarSiSigue: async (followerId, followingId) => {
        if (!followerId || !followingId) return false;
        try {
            const { data, error } = await supabase
                .from('follows')
                .select('id')
                .eq('follower_id', followerId)
                .eq('following_id', followingId)
                .single();

            if (error && error.code !== 'PGRST116') {
                console.error("Error al verificar si sigue:", error);
            }
            return !!data;
        } catch (error) {
            return false;
        }
    },

    obtenerContadoresSeguidores: async (userId) => {
        try {
            // Contar seguidores (la gente que TE sigue)
            const { count: followersCount, error: followersError } = await supabase
                .from('follows')
                .select('*', { count: 'exact', head: true })
                .eq('following_id', userId);

            // Contar seguidos (la gente a la que TÚ sigues)
            const { count: followingCount, error: followingError } = await supabase
                .from('follows')
                .select('*', { count: 'exact', head: true })
                .eq('follower_id', userId);

            if (followersError || followingError) {
                console.error("Error al obtener contadores:", followersError || followingError);
                return { followers: 0, following: 0 };
            }

            return { followers: followersCount || 0, following: followingCount || 0 };
        } catch (error) {
            console.error("Excepción obteniendo contadores:", error);
            return { followers: 0, following: 0 };
        }
    },

    obtenerSiguiendoIds: async (userId) => {
        try {
            const { data, error } = await supabase
                .from('follows')
                .select('following_id')
                .eq('follower_id', userId);

            if (error) throw error;
            return data.map(f => f.following_id);
        } catch (error) {
            console.error("Error obteniendo a quién sigo:", error);
            return [];
        }
    },

    buscarUsuarios: async (busqueda) => {
        if (!busqueda || busqueda.trim().length < 2) return [];

        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('id, username, avatar_url')
                .ilike('username', `%${busqueda}%`)
                .limit(5);

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error("Error buscando usuarios:", error);
            return [];
        }
    }
};
